{
  "summary": "Gather contract terms, renewal/pricing policy, Acme's SLA performance, and any credits owed, then draft a response to Acme's renewal offer.",
  "reply_type": "vendor_email",
  "steps": [
    {
      "id": 1,
      "agent": "retriever",
      "task": "List and read the current Acme Cloud Services contract to find renewal terms, notice period, current pricing, and any price-increase caps or clauses; list and read any internal pricing/renewal policy documents governing acceptable increases; list and read Acme's SLA terms and performance/invoice records for the current contract period; use the SLA credit calculator to determine any SLA misses and credits owed to us that should offset or be factored into the renewal negotiation.",
      "why": "All facts needed for the response (contract terms, policy limits, SLA performance, and money owed) must be retrieved before drafting a reply."
    },
    {
      "id": 2,
      "agent": "executor",
      "task": "Draft a reply to Acme Cloud Services addressing the proposed 12% price increase and 12-month renewal, referencing actual contract terms, any policy caps on increases, and any SLA credits owed to us, proposing a counter-offer if warranted.",
      "why": "The executor synthesizes the gathered facts into the final vendor-facing response for human review and approval."
    }
  ],
  "escalate": null
}
